window.visualViewport?.addEventListener?.('resize', syncViewportCssVars, { passive: true });
window.visualViewport?.addEventListener?.('scroll', syncViewportCssVars, { passive: true });

// Composer textareas auto-size on input, but a window/pane resize re-wraps EXISTING text (a one-liner
// becomes two lines when the window narrows) with no input event — so refit both fields on resize too.
window.addEventListener('resize', () => {
}, { passive: true });

customPublicChannels = readCustomPublicChannels();
rebuildPublicChannelRegistry();
publicChannelSubscriptions = readPublicChannelSubscriptions(publicChannelStorage(), publicChannelRegistry);
writePublicChannelSubscriptions(publicChannelStorage(), publicChannelSubscriptions);
loadPrefsSyncMeta();
refreshGlobalSyncIndicator();
publicChannelFeedCache = readPublicChannelFeedCache(publicChannelStorage());
publicChannelProfileCache = readPublicChannelProfileCache(publicChannelStorage());
// Warm per-wallet avatars from the IndexedDB media store BEFORE the first render so reloaded public feeds show
// faces immediately (no letter-tile placeholder + chain-refetch flash). Top-level await (app.js is a module),
// bounded by a short deadline so a slow/unavailable IndexedDB can never hang boot — past it the remaining
// avatars just hydrate from chain. Then migrate any legacy localStorage avatar cache off-thread.
// Start the branded boot-screen backdrop animation as early as possible (before the avatar-warm wait below),
// so the overlay that is already painted from HTML comes alive immediately.
initBootScreen();
// Warm public POST images from IndexedDB in parallel with author avatars — BOTH before the first render — so a
// reloaded post shows its own image in milliseconds. The localStorage feed cache stripped the image data-url on
// persist, so without this warm the image only came back after the full serial chain walk (~a minute — the
// owner-flagged "re-downloads from the blockchain every time"; it does not re-download, the walk that
// rediscovers the per-part entry ids to consult the durable body cache is what takes the minute). warm mutates
// the in-memory cache posts in place; rebuildThreadsFromPublicSubscriptions below reads them. If the IndexedDB
// read loses the 400ms boot-render race (rare — getMany is ms), re-render once it lands (flag-gated so a warm
// that WON the race — already reflected in the boot render — does not trigger a redundant repaint).
let publicBootFeedRendered = false;
// Warm BOTH media caches from IndexedDB before the first render — sequentially, never a concurrent Promise.all
// (the blanket no-concurrent-read guard; these are local IndexedDB reads, but the rule is a literal ban and
// serial is plenty fast). Bounded by one boot deadline so a slow/unavailable IndexedDB can never hang boot.
const publicBootMediaWarm = (async () => {
  await warmPublicChannelAvatarsFromCache();
  const changed = await warmPublicPostImagesFromCache().catch(() => false);
  // If this warm already landed BEFORE the boot render (won the race), the boot render below reflects it and
  // publicBootFeedRendered is still false → no redundant repaint. If it lands AFTER (slow IndexedDB lost the
  // race), re-render so the post image still appears in ms, not only after the serial chain sync.
  if (changed && publicBootFeedRendered) {
    rebuildThreadsFromPublicSubscriptions({ preserveActive: true });
    renderThreads();
    renderConversation();
  }
  return changed;
})();
await Promise.race([publicBootMediaWarm, delay(400)]);
setTimeout(() => { void migrateLegacyAvatarMediaCacheToIndexedDb(); }, 0);
// One-time cleanup: an EXISTING device cache (written before the strip below) may still hold megabytes of
// base64 media in localStorage — the root of the iOS Vault freeze. Re-persist it through the now-stripping
// writer so the on-disk store shrinks to light metadata. Deferred (setTimeout 0) so the single heavy
// re-serialize of the old store does not block boot; it runs before the user can navigate to the Vault tab.
// The in-memory cache keeps its media for rendering; only the persisted copy is lightened.
setTimeout(() => { try { writePublicChannelFeedCache(publicChannelStorage(), publicChannelFeedCache); } catch {} }, 0);
publicReadCursors = readPublicReadCursors();
rebuildThreadsFromPublicSubscriptions({ preserveActive: false });
renderConfiguredShell();
renderDocsNav();
// The boot public-feed render has now run; a post-image warm that lands AFTER this may re-render (see above).
publicBootFeedRendered = true;
// ── Quick-start onboarding (shown on first run when there is no wallet yet) ──────────────
const quickStartDialog = document.querySelector('#quickStartDialog');
const quickStartWelcomeView = document.querySelector('#quickStartWelcomeView');
const quickStartStepsView = document.querySelector('#quickStartStepsView');
const quickStartBeginButton = document.querySelector('#quickStartBeginButton');
const quickStartImportButtonEl = document.querySelector('#quickStartImportButton');
const quickStartCloseButton = document.querySelector('#quickStartCloseButton');
const quickStartBackButton = document.querySelector('#quickStartBackButton');
const quickStartSkipButton = document.querySelector('#quickStartSkipButton');
const quickStartActionButton = document.querySelector('#quickStartActionButton');
const quickStartProgress = document.querySelector('#quickStartProgress');
const quickStartStepCounter = document.querySelector('#quickStartStepCounter');
const quickStartStepTitle = document.querySelector('#quickStartStepTitle');
const quickStartStepWhy = document.querySelector('#quickStartStepWhy');
const quickStartStepBody = document.querySelector('#quickStartStepBody');
const quickStartStepStatus = document.querySelector('#quickStartStepStatus');
// ── App language (i18n) ─────────────────────────────────────────────────────────────────────
const appLanguageSelect = document.querySelector('#appLanguageSelect');
const quickStartLanguageSelect = document.querySelector('#quickStartLanguageSelect');

function populateLanguageSelect(select) {
  if (!select) return;
  select.innerHTML = '';
  for (const locale of I18N_LOCALES) {
    const option = document.createElement('option');
    option.value = locale.code;
    // Endonyms on purpose: a user hunting for their language must recognize it without knowing the current one.
    option.textContent = locale.native;
    select.append(option);
  }
  select.value = currentLocale();
}

populateLanguageSelect(appLanguageSelect);
populateLanguageSelect(quickStartLanguageSelect);

// Profile switch reloads: dynamic renders bake t() output into DOM all over the app, and a reload is the only
// switch that provably leaves no stale-language text (sends survive reloads by design — persisted publish state).
appLanguageSelect?.addEventListener('change', () => {
  setLocale(appLanguageSelect.value);
  window.location.reload();
});

// Quick-start switch applies in place: pre-wallet there is nothing dynamic rendered yet, and a reload here
// would visibly restart the dialog the user just opened.
quickStartLanguageSelect?.addEventListener('change', () => {
  setLocale(quickStartLanguageSelect.value);
  applyStaticTranslations();
  if (appLanguageSelect) appLanguageSelect.value = currentLocale();
  // Re-render the stepper ONLY if it is actually open: renderQuickStartStep persists progress (resume-on-boot)
  // and may auto-advance — neither is welcome while the user is still on the welcome view.
  if (quickStartStepsView && !quickStartStepsView.hidden) renderQuickStartStep();
});

const QUICK_START_DISMISSED_KEY = 'platho.quickstart.dismissed.v1';
const QUICK_START_DISMISSED_CLOUD_KEY = 'platho_quickstart_dismissed_v1';
// Persisted so an in-progress quick start SURVIVES a reload or a background auto-lock (going to another wallet
// app to top up then returning locks Platho — without this the stepper is gone and, since a wallet now exists,
// never re-surfaces). Stores the active step index; cleared on finish / dismiss-forever.
const QUICK_START_PROGRESS_KEY = 'platho.quickstart.step.v1';

function quickStartDismissedForever() {
  try { return globalThis.localStorage?.getItem(QUICK_START_DISMISSED_KEY) === '1'; } catch { return false; }
}

function saveQuickStartProgress(stepIndex) {
  try { globalThis.localStorage?.setItem(QUICK_START_PROGRESS_KEY, String(stepIndex)); } catch { /* ignore */ }
}

function readQuickStartProgress() {
  try {
    const raw = globalThis.localStorage?.getItem(QUICK_START_PROGRESS_KEY);
    if (raw === null || raw === undefined || raw === '') return null;
    const n = Number(raw);
    return Number.isInteger(n) && n >= 0 ? n : null;
  } catch { return null; }
}

function clearQuickStartProgress() {
  try { globalThis.localStorage?.removeItem(QUICK_START_PROGRESS_KEY); } catch { /* ignore */ }
}

// Last-read external wallet GRAM balance in nanotons (from the shared vaultPocketState), or null if unknown.
function quickStartWalletTonNanotons() {
  const raw = vaultPocketState?.wallet?.ton_balance;
  if (raw === null || raw === undefined) return null;
  try { return BigInt(raw); } catch { return null; }
}

// iOS Telegram can evict localStorage between sessions, so a wallet-less user who
// dismissed the welcome would re-see it every launch. Mirror the dismissal into
// Telegram CloudStorage (no-op outside Telegram) and restore it on boot.
async function restoreQuickStartDismissalFromTelegramCloud() {
  if (!telegramCloudStorage()) return;
  if (quickStartDismissedForever()) return;
  try {
    if ((await telegramCloudGet(QUICK_START_DISMISSED_CLOUD_KEY)) === '1') {
      try { globalThis.localStorage?.setItem(QUICK_START_DISMISSED_KEY, '1'); } catch { /* ignore */ }
    }
  } catch { /* ignore */ }
}

async function runQuickStartCreateWallet() {
  if (hasStoredPlathoWalletRecord()) return true;
  const walletDraft = await createPlathoWallet(plathoWalletNetworkOptions());
  const password = await requestNewWalletStoragePassword(t('wallet.encryptNewWallet'), {
    passwordManagerUsername: walletDraft.address,
    passwordManagerNetworkGlobalId: walletDraft.networkGlobalId,
  });
  if (!password) return false;
  await setPlathoWallet(walletDraft, { password });
  markWalletKeyBackupPending(walletDraft.address);
  await enforceTelegramSeedBackupGate(walletDraft, { force: true });
  flashWalletIdentityStatus(t('wallet.walletReady'));
  refreshMessagingControls();
  return true;
}

// Refresh the external wallet GRAM balance into vaultPocketState (no step re-render — callers update in place).
// Reads the RECEIVE ADDRESS balance directly (public info) instead of requiring the unlocked wallet: onboarding can
// reach the top-up/activate steps with the wallet record stored but NOT loaded into runtime (step 1 auto-dones on
// the stored record after a resume/background-lock without unlocking), and requiring plathoWallet left the balance
// stuck on "checking…" forever.
async function quickStartRefreshWalletBalanceRaw() {
  const address = currentWalletReceiveAddress();
  if (!address) return;
  try {
    const balance = await loadConnectedTonWalletBalance(address);
    vaultPocketState = {
      wallet: { ton_balance: balance, ath_balance: vaultPocketState.wallet?.ath_balance ?? null },
    };
  } catch (error) { if (!noteTonRpcRateLimit(error)) console.error(error); }
}

// Jump the stepper to a named step (used by "Back to Top up" on the activation step).
function quickStartGoToStepByKey(key) {
  quickStartStepIndex = quickStartStepIndexByKey(key);
  renderQuickStartStep();
}

// Top-up step body: receive address + a LIVE balance line so a user who just sent GRAM from another wallet app
// sees it arrive (auto-checked on entry + a manual "Check balance"). In-place text updates, never a re-render.
function buildQuickStartTopUpBody() {
  const wrap = document.createElement('div');
  wrap.className = 'quick-start-key-body';
  const addr = document.createElement('div');
  addr.className = 'quick-start-step-address';
  addr.textContent = currentWalletReceiveAddress() || storedWalletAddressForCopy() || t('quickstart.createWalletFirst');
  const balanceLine = document.createElement('div');
  balanceLine.className = 'quick-start-balance-line';
  const check = document.createElement('button');
  check.type = 'button';
  check.className = 'discovery-cta-action';
  check.textContent = t('quickstart.checkBalance');
  const renderBalance = () => {
    const bal = quickStartWalletTonNanotons();
    balanceLine.textContent = bal === null ? t('quickstart.balanceChecking') : t('quickstart.walletBalance', { balance: formatTonNanotons(bal) });
  };
  const refresh = async () => {
    balanceLine.textContent = t('quickstart.balanceChecking');
    await quickStartRefreshWalletBalanceRaw();
    renderBalance();
  };
  check.addEventListener('click', () => { refresh(); });
  renderBalance();
  refresh();
  wrap.append(addr, balanceLine, check);
  return wrap;
}

// Activation step body: shows balance vs the activation fee and GATES on funds — an underfunded wallet cannot
// activate, so instead of letting the on-chain send fail, disable the action and offer "Back to Top up".
function buildQuickStartActivateBody() {
  // Same stacking layout as the Top-up step (quick-start-key-body: grid + 12px gap) so the balance,
  // hint and the two actions never glue together, and both actions use the shared plate-CTA class
  // (.discovery-cta-action) so they read as buttons — the same "Add contact" look as the rest of the app.
  const wrap = document.createElement('div');
  wrap.className = 'quick-start-key-body';
  const summary = document.createElement('div');
  summary.className = 'quick-start-balance-line';
  const hint = document.createElement('div');
  hint.className = 'quick-start-step-hint';
  const check = document.createElement('button');
  check.type = 'button';
  check.className = 'discovery-cta-action';
  check.textContent = t('quickstart.checkBalance');
  const backBtn = document.createElement('button');
  backBtn.type = 'button';
  backBtn.className = 'discovery-cta-action';
  backBtn.textContent = t('quickstart.backToTopUp');
  backBtn.addEventListener('click', () => { quickStartGoToStepByKey('topup'); });
  const applyGate = () => {
    const bal = quickStartWalletTonNanotons();
    const fee = plathoAccountActivationFeeNanotons();
    summary.textContent = bal === null
      ? t('quickstart.activationNeedsChecking', { fee: formatTonNanotons(fee) })
      : t('quickstart.balanceActivationNeeds', { balance: formatTonNanotons(bal), fee: formatTonNanotons(fee) });
    const underfunded = bal !== null && bal < fee;
    backBtn.hidden = !underfunded;
    hint.textContent = underfunded ? t('quickstart.notEnoughGramHint') : '';
    hint.classList.toggle('is-error', underfunded);
    // Block the on-chain send when we KNOW the wallet is short; leave it enabled while the balance is unknown
    // (run() double-checks and returns guidance instead of a doomed activation). renderQuickStartStep runs
    // body() BEFORE it sets the action label, and setting textContent does not touch .disabled, so this sticks.
    if (quickStartActionButton) quickStartActionButton.disabled = underfunded;
  };
  const refresh = async () => {
    await quickStartRefreshWalletBalanceRaw();
    applyGate();
  };
  check.addEventListener('click', () => { refresh(); });
  applyGate();
  refresh();
  wrap.append(summary, hint, check, backBtn);
  return wrap;
}

const QUICK_START_STEPS = [
  {
    title: t('quickstart.createWalletTitle'),
    action: t('quickstart.createWalletAction'),
    optional: false,
    why: t('quickstart.createWalletWhy'),
    autoDone: () => hasStoredPlathoWalletRecord(),
    body: () => null,
    run: () => runQuickStartCreateWallet(),
  },
  {
    title: t('quickstart.addKeyTitle'),
    action: t('quickstart.saveKeyAction'),
    optional: true,
    why: t('quickstart.addKeyWhy'),
    autoDone: () => false,
    body: () => {
      // Input FIRST, the get-a-key CTA below it with a clear gap (owner: the old order glued a
      // button-that-didn't-look-like-one on top of the field). The CTA reuses the shared plate-action
      // button class so it reads unmistakably as a button (same look as "Add contact").
      const wrap = document.createElement('div');
      wrap.className = 'quick-start-key-body';
      const input = document.createElement('input');
      input.type = 'text';
      input.id = 'quickStartKeyInput';
      input.autocomplete = 'off';
      input.spellcheck = false;
      input.placeholder = t('quickstart.pasteKeyPlaceholder');
      if (globalThis.plathoToncenterApiKey) input.value = globalThis.plathoToncenterApiKey;
      const getKey = document.createElement('button');
      getKey.type = 'button';
      getKey.className = 'discovery-cta-action';
      getKey.textContent = t('quickstart.getFreeKey');
      getKey.addEventListener('click', () => { openToncenterBotLink(); });
      wrap.append(input, getKey);
      return wrap;
    },
    run: async () => {
      const value = quickStartStepBody?.querySelector('#quickStartKeyInput')?.value;
      const trimmed = String(value ?? '').trim();
      if (!trimmed) return false;
      const result = await validateToncenterApiKey(trimmed);
      if (result.reason === 'invalid') return t('quickstart.keyRejected');
      applyToncenterApiKey(trimmed);
      return true;
    },
  },
  {
    key: 'export',
    title: t('quickstart.backupKeyTitle'),
    action: t('quickstart.saveWalletKeyAction'),
    optional: false,
    why: t('quickstart.backupKeyWhy'),
    autoDone: () => false,
    body: () => null,
    run: () => exportEncryptedWalletKeyFile(),
  },
  {
    key: 'topup',
    title: t('quickstart.topUpTitle'),
    action: t('quickstart.copyAddressAction'),
    optional: true,
    why: t('quickstart.topUpWhy'),
    autoDone: () => false,
    body: () => buildQuickStartTopUpBody(),
    run: async () => {
      const address = currentWalletReceiveAddress() || storedWalletAddressForCopy() || '';
      if (!address) return false;
      await copyTextToClipboard(address);
      return true;
    },
  },
  {
    key: 'activate',
    title: t('quickstart.activateTitle'),
    action: t('quickstart.activateAction'),
    optional: true,
    why: t('quickstart.activateWhy'),
    autoDone: () => hasActivePlathoAccount(),
    body: () => buildQuickStartActivateBody(),
    run: async () => {
      // Gate on funds so activation never fails on an empty wallet — send the user back to Top up instead.
      const bal = quickStartWalletTonNanotons();
      const fee = plathoAccountActivationFeeNanotons();
      if (bal !== null && bal < fee) {
        return t('quickstart.notEnoughToActivate', { balance: formatTonNanotons(bal), fee: formatTonNanotons(fee) });
      }
      await submitVaultRegisterMessagingKeys();
      return true;
    },
  },
];

let quickStartStepIndex = 0;

function renderQuickStartProgress() {
  if (!quickStartProgress) return;
  quickStartProgress.innerHTML = '';
  QUICK_START_STEPS.forEach((_, i) => {
    const dot = document.createElement('span');
    dot.className = 'quick-start-progress-dot';
    if (i < quickStartStepIndex) dot.classList.add('is-done');
    else if (i === quickStartStepIndex) dot.classList.add('is-current');
    quickStartProgress.appendChild(dot);
  });
}

function renderQuickStartStep() {
  const step = QUICK_START_STEPS[quickStartStepIndex];
  if (!step) { finishQuickStart(); return; }
  // A mandatory step that is already satisfied (e.g. a wallet already exists) is auto-skipped.
  if (!step.optional && step.autoDone()) { quickStartAdvance(); return; }
  renderQuickStartProgress();
  setText(quickStartStepCounter, t('quickstart.stepCounter', { n: quickStartStepIndex + 1, total: QUICK_START_STEPS.length }));
  setText(quickStartStepTitle, step.title);
  setText(quickStartStepWhy, step.why);
  setText(quickStartStepStatus, '');
  if (quickStartStepBody) {
    quickStartStepBody.innerHTML = '';
    const body = step.body();
    if (body) quickStartStepBody.appendChild(body);
  }
  if (quickStartActionButton) quickStartActionButton.textContent = step.action;
  if (quickStartBackButton) quickStartBackButton.hidden = quickStartStepIndex === 0;
  if (quickStartSkipButton) quickStartSkipButton.hidden = !step.optional;
  // Persist the active step so a reload / background auto-lock resumes here (NOT in backup-only mode, which
  // re-surfaces on its own via the pending-backup nudge).
  if (!quickStartBackupMode) saveQuickStartProgress(quickStartStepIndex);
}

function quickStartAdvance() {
  if (quickStartStepIndex >= QUICK_START_STEPS.length - 1) { finishQuickStart(); return; }
  quickStartStepIndex += 1;
  renderQuickStartStep();
}

// When the quick-start is re-opened ONLY to finish the mandatory wallet-key backup (a wallet already
// exists), closing it must NOT permanently dismiss onboarding — the backup is still pending and should
// re-surface next launch. quickStartBackupMode tracks that so closeQuickStart skips the dismissed-forever flag.
let quickStartBackupMode = false;

function closeQuickStart() {
  if (quickStartDialog) quickStartDialog.hidden = true;
  if (!quickStartBackupMode) {
    // Explicit dismissal (X / Skip-out): stop onboarding for good AND drop the in-progress resume marker.
    try { globalThis.localStorage?.setItem(QUICK_START_DISMISSED_KEY, '1'); } catch { /* ignore */ }
    try { telegramCloudSet(QUICK_START_DISMISSED_CLOUD_KEY, '1').catch(() => {}); } catch { /* ignore */ }
    clearQuickStartProgress();
  }
  quickStartBackupMode = false;
}

function finishQuickStart() {
  clearQuickStartProgress();
  closeQuickStart();
  flashWalletIdentityStatus(t('quickstart.setupComplete'));
}

// Resume the stepper at a specific step (reload / after a background auto-lock + unlock). Unlike openQuickStart,
// it skips the welcome view and jumps straight to where the user left off.
function openQuickStartAtStep(index) {
  if (!quickStartDialog) return;
  quickStartBackupMode = false;
  quickStartStepIndex = Math.max(0, Math.min(Number(index) || 0, QUICK_START_STEPS.length - 1));
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = true;
  if (quickStartStepsView) quickStartStepsView.hidden = false;
  quickStartDialog.hidden = false;
  renderQuickStartStep();
}

// After a background auto-lock + unlock, bring the user straight back to the quick-start step they were on
// (e.g. they hopped to another wallet app to top up). No-op if it was dismissed.
function maybeResumeQuickStartAfterUnlock() {
  if (!quickStartDialog) return;
  if (quickStartDismissedForever()) return;
  if (quickStartDialog.hidden === false) {
    // Still open (it sat behind the lock screen): just re-check a balance step now that reads work again.
    quickStartRefreshCurrentBalanceStep();
    return;
  }
  const savedStep = readQuickStartProgress();
  if (savedStep !== null) openQuickStartAtStep(savedStep);
}

// Re-render the stepper IF it is showing a balance step (Top up / Activate) so it re-reads the wallet balance —
// used on return-to-foreground and after unlock so arrived funds show without a manual "Check balance".
function quickStartRefreshCurrentBalanceStep() {
  if (!quickStartDialog || quickStartDialog.hidden !== false) return;
  if (!quickStartStepsView || quickStartStepsView.hidden) return;
  const key = QUICK_START_STEPS[quickStartStepIndex]?.key;
  if (key === 'topup' || key === 'activate') renderQuickStartStep();
}

function openQuickStart() {
  if (!quickStartDialog) return;
  quickStartBackupMode = false;
  quickStartStepIndex = 0;
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = false;
  if (quickStartStepsView) quickStartStepsView.hidden = true;
  quickStartDialog.hidden = false;
}

function quickStartStepIndexByKey(key) {
  const i = QUICK_START_STEPS.findIndex((step) => step.key === key);
  return i >= 0 ? i : 0;
}

// Re-open the quick-start jumped straight to the mandatory wallet-key backup step (used when a wallet exists
// but its key was never exported). The export step itself prompts for the password, so the wallet does not
// need to be unlocked first.
function openQuickStartAtBackup() {
  if (!quickStartDialog) return;
  quickStartBackupMode = true;
  quickStartStepIndex = quickStartStepIndexByKey('export');
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = true;
  if (quickStartStepsView) quickStartStepsView.hidden = false;
  quickStartDialog.hidden = false;
  renderQuickStartStep();
}

function maybeShowQuickStartOnFirstRun() {
  if (!quickStartDialog) return false;
  // Resume an in-progress quick start FIRST (user began, then reloaded / backgrounded-and-locked): jump straight
  // to the saved step even though a wallet now exists — otherwise onboarding silently vanishes after step 1.
  const savedStep = readQuickStartProgress();
  if (savedStep !== null && !quickStartDismissedForever()) {
    openQuickStartAtStep(savedStep);
    return true;
  }
  if (!hasStoredPlathoWalletRecord()) {
    if (quickStartDismissedForever()) return false;
    openQuickStart();
    return true;
  }
  // A wallet exists but its encrypted key was never exported — keep nudging the backup until it is done.
  if (walletKeyBackupPendingForStoredWallet()) {
    openQuickStartAtBackup();
    return true;
  }
  return false;
}

quickStartBeginButton?.addEventListener('click', () => {
  quickStartStepIndex = 0;
  if (quickStartWelcomeView) quickStartWelcomeView.hidden = true;
  if (quickStartStepsView) quickStartStepsView.hidden = false;
  renderQuickStartStep();
});
quickStartCloseButton?.addEventListener('click', () => closeQuickStart());
quickStartImportButtonEl?.addEventListener('click', () => { closeQuickStart(); walletKeyBackupInput?.click(); });
quickStartBackButton?.addEventListener('click', () => { if (quickStartStepIndex > 0) { quickStartStepIndex -= 1; renderQuickStartStep(); } });
quickStartSkipButton?.addEventListener('click', () => quickStartAdvance());
quickStartActionButton?.addEventListener('click', async () => {
  const step = QUICK_START_STEPS[quickStartStepIndex];
  if (!step || !quickStartActionButton) return;
  quickStartActionButton.disabled = true;
  setText(quickStartStepStatus, t('quickstart.working'));
  try {
    const ok = await step.run();
    if (typeof ok === 'string') {
      // The step supplied its own failure message (e.g. an invalid key) — show it, do not advance.
      setText(quickStartStepStatus, ok);
    } else if (ok === false) {
      setText(quickStartStepStatus, step.optional ? t('quickstart.nothingEntered') : t('quickstart.notCompleted'));
    } else {
      setText(quickStartStepStatus, t('quickstart.done'));
      quickStartAdvance();
    }
  } catch (error) {
    console.error(error);
    setText(quickStartStepStatus, step.optional
      ? t('quickstart.couldNotCompleteLater')
      : t('quickstart.couldNotComplete', { reason: error?.message ?? t('quickstart.tryAgain') }));
  } finally {
    quickStartActionButton.disabled = false;
  }
});

// ---- Emoji picker ----------------------------------------------------------------------------------------------
// A self-contained unicode-emoji picker (NO external font/library — CSP style-src 'self'). ONE global fixed popover
// shared by the private + public composers (kept out of the panes so a tab switch never hides it), inserts at the
// target textarea's caret and dispatches 'input' so the composer's cost/draft/auto-resize listeners fire. Positioned
// via CSSOM left/bottom (per-property assignment is CSP-allowed, unlike setAttribute('style')).
const PLATHO_EMOJI_LIST = [
  '😀','😃','😄','😁','😆','😅','😂','🤣','🥲','😊','🙂','🙃','😉','😌','😍','🥰','😘','😋','😛','😜','🤪','😝','🤗','🤭','🤔','🤐','😶','😏','😒','🙄','😬','😔','😴','😷','🤒','🤢','🤮','🥵','🥶','😵',
  '🤯','🥳','😎','🤓','🧐','🙁','😣','😖','😫','😩','🥺','😢','😭','😤','😠','😡',
  '👍','👎','👌','🤌','🤏','✌️','🤞','🤟','🤘','🤙','👈','👉','👆','👇','☝️','✋','👋','💪','🙏','🤲','👐','🙌','👏','🤝',
  '❤️','🧡','💛','💚','💙','💜','🖤','🤍','🤎','💔','❣️','💕','💞','💓','💗','💖',
  '🔥','✨','⭐','🌟','💫','💥','💯','🎉','🎊','🎈','🎁','🌈','☀️','🌙','⚡','👑','💎','🥂','🍻','☕','🍕','🍑','👀','💀',
];
const emojiPicker = document.querySelector('#emojiPicker');
const emojiPickerGrid = document.querySelector('#emojiPickerGrid');
let emojiPickerTargetInput = null;
let emojiPickerTargetButton = null;

// Insert emoji (or the link dialog's markup) at the editor caret. A picker opened BEFORE the composer got
// blocked can outlive its (now-disabled) trigger button — never write into a disabled editor.
function insertEmojiAtCaret(input, emoji) {
  if (!input || input.disabled) return;
  composerEditorInsertText(input, emoji);
}

function positionEmojiPicker(button) {
  if (!emojiPicker || !button) return;
  const rect = button.getBoundingClientRect();
  const width = emojiPicker.offsetWidth; // measured after the picker is shown (display:block)
  const height = emojiPicker.offsetHeight;
  const left = Math.max(8, Math.min(rect.left, window.innerWidth - width - 8));
  emojiPicker.style.left = `${left}px`;
  // Normally open UPWARD (the composer sits at the bottom). But a MAXIMIZED composer puts the toolbar/emoji button at
  // the TOP of the full-screen overlay, so opening up would run off-screen — fall back to opening downward when there
  // isn't room above. (CSSOM per-property assignment only — prod CSP blocks setAttribute('style').)
  if (rect.top >= height + 8) {
    emojiPicker.style.top = 'auto';
    emojiPicker.style.bottom = `${Math.max(8, window.innerHeight - rect.top + 8)}px`;
  } else {
    emojiPicker.style.bottom = 'auto';
    emojiPicker.style.top = `${Math.min(rect.bottom + 8, Math.max(8, window.innerHeight - height - 8))}px`;
  }
}

function closeEmojiPicker() {
  if (!emojiPicker || emojiPicker.hidden) return;
  emojiPicker.hidden = true;
  emojiPickerTargetButton?.setAttribute('aria-expanded', 'false');
  emojiPickerTargetInput = null;
  emojiPickerTargetButton = null;
}

function openEmojiPicker(button, input) {
  if (!emojiPicker || !button) return;
  emojiPickerTargetInput = input;
  emojiPickerTargetButton = button;
  emojiPicker.hidden = false;
  positionEmojiPicker(button);
  button.setAttribute('aria-expanded', 'true');
}

function toggleEmojiPicker(button, input) {
  if (!emojiPicker) return;
  if (!emojiPicker.hidden && emojiPickerTargetButton === button) { closeEmojiPicker(); return; }
  openEmojiPicker(button, input);
}

function setupEmojiPicker() {
  if (!emojiPicker || !emojiPickerGrid) return;
  for (const emoji of PLATHO_EMOJI_LIST) {
    const item = document.createElement('button');
    item.type = 'button';
    item.className = 'emoji-picker-item';
    item.textContent = emoji;
    item.setAttribute('aria-label', emoji);
    item.addEventListener('click', () => {
      const target = emojiPickerTargetInput;
      closeEmojiPicker(); // pick-then-close: one tap inserts and dismisses the panel
      if (target) insertEmojiAtCaret(target, emoji);
    });
    emojiPickerGrid.appendChild(item);
  }
  privateEmojiButton?.addEventListener('click', () => toggleEmojiPicker(privateEmojiButton, messageInput));
  publicEmojiButton?.addEventListener('click', () => toggleEmojiPicker(publicEmojiButton, publicMessageInput));
  document.addEventListener('click', (event) => {
    if (emojiPicker.hidden) return;
    if (emojiPicker.contains(event.target) || privateEmojiButton?.contains(event.target) || publicEmojiButton?.contains(event.target)) return;
    closeEmojiPicker();
  });
  document.addEventListener('keydown', (event) => { if (event.key === 'Escape' && !emojiPicker.hidden) closeEmojiPicker(); });
  window.addEventListener('resize', () => { if (!emojiPicker.hidden && emojiPickerTargetButton) positionEmojiPicker(emojiPickerTargetButton); });
}
setupEmojiPicker();

renderAthProfileStats();
updatePublicSyncWindowUi();
updatePublicCommentsDefaultUi();
updatePrivateSenderModeUi();
setPublicCommentTarget(null);
rebuildThreadsFromPublicSubscriptions({ preserveActive: false });
if (activeThreadId) {
  appShell.dataset.chatOpen = 'true';
} else if (publicChannelThreads.length > 0) {
  appShell.dataset.chatOpen = 'false';
  setView('public');
} else {
  appShell.dataset.chatOpen = 'false';
}
installNavBackHandling();
renderThreads();
renderConversation();
refreshMessagingControls();
// Start the unified background sync loop regardless of the initial tab or wallet state: it ticks the public
// feed immediately and picks up private messages once a wallet/keys are present. It self-suspends on
// document.hidden and re-arms on visibility/focus/pageshow.
scheduleMessageAutoSync(2_000);
document.documentElement.dataset.plathoAppJs = 'ready';
bootCrypto()
  .then(() => { setBootDebug('crypto-locked'); })
  // ALL Telegram-CloudStorage restores are bounded by a single race: telegramCloudGet has no timeout, so a slow
  // or hung CloudStorage (mobile / Telegram WebView) could otherwise stall the whole chain BEFORE the unlock
  // decision — an eternal boot screen with no modal. They keep running in the background; the decision below
  // uses whatever local state is ready by the cap. (CloudStorage reads, not toncenter — outside the
  // PWA-FUNDS-SERIAL-01 concern; and no Promise.all array literal: the reads are chained, then raced.)
  .then(() => {
    setBootDebug('restore');
    const walletRestore = restoreWalletRecordFromTelegramCloud().catch(() => false);
    const dismissalRestore = restoreQuickStartDismissalFromTelegramCloud().catch(() => {});
    const backupRestore = restoreWalletKeyBackupPendingFromTelegramCloud().catch(() => {});
    return Promise.race([
      walletRestore.then(() => dismissalRestore).then(() => backupRestore),
      delay(2500),
    ]).catch(() => {});
  })
  .then(() => {
    try { refreshWalletBackupWarning(); } catch (error) { console.error(error); }
    // If we are driving the user through the mandatory wallet-key backup (a wallet exists but its key was
    // never exported), the backup step does its own unlock — don't also pop the startup unlock prompt
    // (avoids a confusing double password). Otherwise unlock as usual.
    const drivingBackup = walletKeyBackupPendingForStoredWallet();
    let quickStartShown = false;
    try { quickStartShown = maybeShowQuickStartOnFirstRun(); } catch (error) { console.error(error); }
    const hasWallet = hasStoredPlathoWalletRecord();
    setBootDebug(`decide wallet=${hasWallet ? 1 : 0} locked=${plathoWallet ? 0 : 1} backup=${drivingBackup ? 1 : 0} qs=${quickStartShown ? 1 : 0}`);
    // Quick-start / backup dialogs are modal-backdrops (z-index 40) that the overlay (55) would bury — reveal
    // the app before they show. The overlay stays up ONLY for the pure password-unlock path.
    if (quickStartShown || drivingBackup) {
      markBootAppReady();
      if (!drivingBackup) promptStoredWalletUnlockOnStartup().catch((error) => console.error(error));
      return;
    }
    if (hasWallet && !plathoWallet) {
      // Stored + locked: drive the unlock ON the overlay and keep it up until the core is ready / cancelled.
      void runBootScreenUnlock();
    } else {
      // Nothing to unlock (no wallet, or already unlocked) — reveal the app.
      markBootAppReady();
    }
  })
  .catch((error) => { setBootDebug(`boot-chain-err ${error?.message ?? error}`); console.error(error); });
